import pytest
import json
from pathlib import Path
from validator import SwaggerSchemaValidator
from requests.exceptions import HTTPError

# Load test data from JSON file
_here = Path(__file__).resolve().parent
TEST_DATA_FILENAME = 'pet_petId.json'
_endpoint_data_path = _here / TEST_DATA_FILENAME
with open(_endpoint_data_path) as f:
    _ENDPOINT_TEST_DATA = json.load(f)

# Swagger schema validator setup
SWAGGER_SPEC_PATH = 'api.json'
validator = SwaggerSchemaValidator(SWAGGER_SPEC_PATH)

# Reusable parametrize args
_PARAM_CASES = _ENDPOINT_TEST_DATA
_PARAM_IDS = [f"{case['scenario']}" for case in _ENDPOINT_TEST_DATA]

@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_update_pet_with_form(api_client, petstore_auth, scenario_case):
    """
    Test updating a pet with form data. Covers multiple scenarios based on test data.
    """

    pet_id = scenario_case.get("petId")
    name = scenario_case.get("name")
    status = scenario_case.get("status")
    expected_status_code = scenario_case.get("statusCode")

    endpoint = f"/pet/{pet_id}"
    params = {"name": name, "status": status}

    # Validate request schema
    request_data = {"name": name, "status": status}
    validation_result = validator.validate_json(request_data, "Pet")
    assert validation_result["valid"], f"Request validation failed: {validation_result.get('message')}"

    try:
        response = api_client.post(endpoint, data=params, headers={"Authorization": f"Bearer {petstore_auth}"})
        assert response.status_code == expected_status_code, f"Expected {expected_status_code}, got {response.status_code}"

        # Validate response schema
        schema_validation = validator.validate_schema_by_response(endpoint, "post", str(expected_status_code), response)
        assert schema_validation["valid"], f"Response validation failed: {schema_validation.get('message')}"

    except HTTPError as e:
        if expected_status_code != 200:
            assert True
        else:
            pytest.fail(f"HTTPError occurred: {str(e)}")

